import horizon

def parse(line):
    """'volume = 75' -> ('volume', 75.0). Positions count from 0."""
    eq = horizon.string.find(line, "=")
    if eq < 0:
        return None
    key = horizon.string.trim(horizon.string.substring(line, 0, eq))
    rest = horizon.string.substring(line, eq + 1, horizon.string.length(line))
    return key, horizon.string.toNumber(rest)

class Settings(horizon.Behavior):
    def on_start(self):
        parsed = parse("volume = 75")
        if parsed:
            key, value = parsed
            horizon.log(f"{key} is {value}")

import horizon

class PauseMenu(horizon.Behavior):
    # "Pause" is an input action with "Fires while the game is paused"
    # ticked; without it the second press would never arrive.
    def on_input_pressed(self, name):
        if name != "Pause":
            return
        if horizon.time.isPaused():
            horizon.time.resume()
        else:
            horizon.time.pause()

    def on_collision_enter(self, other):
        horizon.time.hitStop(0.1)   # a landed hit freezes for a tenth of a second

import horizon

class Reminders(horizon.Behavior):
    def on_start(self):
        self.autosave = horizon.timer.every(30)
        self.hint = horizon.timer.after(5)

    def on_timer(self, handle):
        if handle == self.autosave:
            horizon.log("autosave")
        elif handle == self.hint:
            horizon.log("Press E to open the door")
        # any other handle belongs to another script

import horizon

class BossGate(horizon.Behavior):
    # Opens the gate once the boss is gone. Look the ids up once, not every
    # frame: findByName walks every named entity.
    def on_start(self):
        self.boss = horizon.entity.findByName("Boss")
        self.gate = horizon.entity.findByName("Gate")

    def on_update(self, dt):
        if self.gate != 0 and not horizon.entity.exists(self.boss):
            horizon.entity.destroy(self.gate)   # takes its children along
            self.gate = 0

import horizon

class CaveStream(horizon.Behavior):
    # This entity is a trigger volume at the start of the corridor. The cave
    # loads hidden, 200 m along X, while the player walks; the door shows it.
    def on_start(self):
        self.zone = 0

    def on_begin_overlap(self, other):
        if self.zone:
            return
        # The position takes FOUR numbers from a script; the fourth is ignored.
        self.zone = horizon.scene.loadAdditive("Scenes/Cave.hescene", True, 200, 0, 0, 0)

    # "Interact" is an input action.
    def on_input_pressed(self, name):
        if name == "Interact" and self.zone:
            horizon.scene.showZone(self.zone)   # queued behind the load

import horizon

class TutorialHint(horizon.Behavior):
    def on_start(self):
        if not horizon.prefs.getBool("tutorial.skip", False):
            horizon.log("Tutorial: press Space to jump")

    # "SkipTutorial" is an input action, e.g. on the hint's close button.
    def on_input_pressed(self, name):
        if name == "SkipTutorial":
            horizon.prefs.setBool("tutorial.skip", True)   # on disk at once
